exercises.solutionCode:
#include <stddef.h>
#include <string.h>

typedef struct {
    const char *name;
    int (*init)(void);
} DriverEntry;

int driver_register(DriverEntry *table, int cap, int *count, const DriverEntry *entry)
{
    if (table == NULL || count == NULL || entry == NULL ||
        entry->name == NULL || entry->init == NULL) {
        return -1;
    }
    if (cap <= 0 || *count < 0) {
        return -1;
    }
    if (*count >= cap) {
        return -2;  /* 表已满 */
    }

    for (int i = 0; i < *count; i++) {
        if (table[i].name != NULL && strcmp(table[i].name, entry->name) == 0) {
            return -3;  /* 名字重复 */
        }
    }

    table[*count].name = entry->name;
    table[*count].init = entry->init;
    (*count)++;
    return 0;
}

const DriverEntry *driver_find(const DriverEntry *table, int count, const char *name)
{
    if (table == NULL || name == NULL || count <= 0) {
        return NULL;
    }

    for (int i = 0; i < count; i++) {
        if (table[i].name != NULL && strcmp(table[i].name, name) == 0) {
            return &table[i];
        }
    }
    return NULL;
}
